python3 - <<'PY'
import re,glob,os
table={}
for line in open('draft/numerals.md'):
    m=re.match(r'\|\s*(\d+)\s*\|\s*(.+?)\s*\|',line)
    if m: table[m.group(1)]=m.group(2)
alltext=open('draft/08-detailed-description.md').read()
for f in sorted(glob.glob('figures/FIG-*.md')):
    txt=open(f).read()
    body,_,lst=txt.partition('## Numerals shown on this figure')
    listed=set(re.findall(r'^- (\d+)$',lst,re.M))
    used=set(re.findall(r'\b(\d{2})\b',body))
    used={u for u in used if u in table}
    print(os.path.basename(f), 'count=%d'%len(listed), 'chars=%d'%len(txt))
    if used-listed: print('   used not listed:',sorted(used-listed))
    if listed-used: print('   listed not used:',sorted(listed-used))
    unknown=listed-set(table)
    if unknown: print('   not in table:',sorted(unknown))
figs=set()
for f in glob.glob('figures/FIG-*.md'):
    figs.add(int(re.search(r'FIG-(\d+)',f).group(1)))
print('figures:',sorted(figs))
desc_used=set(re.findall(r'\b(\d{2})\b',alltext))&set(table)
print('table numerals missing from description:',sorted(set(table)-desc_used))
figall=set()
for f in glob.glob('figures/FIG-*.md'):
    figall|=set(re.findall(r'^- (\d+)$',open(f).read(),re.M))
print('table numerals on no figure:',sorted(set(table)-figall))
PY
